1	import * as cheerio from 'cheerio';
2	import type { AnyNode } from 'domhandler';
3	
4	export type CompareMode = 'exact' | 'gte' | 'lte' | 'range' | 'approx';
5	
6	export type AccuracyCheck = {
7	  name: string;
8	  category: string;
9	  description: string;
10	  sql: string;
11	  expected: number;
12	  mode: CompareMode;
13	  tolerance?: number;
14	  source: string;
15	};
16	
17	type ExpectedShape = Pick<AccuracyCheck, 'mode' | 'expected'> &
18	  Partial<Pick<AccuracyCheck, 'tolerance'>>;
19	
20	export type Outcome = AccuracyCheck & {
21	  actual: number | null;
22	  passed: boolean;
23	  error: string | null;
24	};
25	
26	export type BbrPlayerSeed = {
27	  name: string;
28	  bbrId: string;
29	  url?: string;
30	};
31	
32	export type BbrCareerTotals = Partial<Record<BbrStatKey, number>>;
33	
34	type BbrStatKey = 'g' | 'pts' | 'trb' | 'ast' | 'stl' | 'blk' | 'fg3';
35	
36	const BBR_CAREER_STAT_LABELS = {
37	  g: 'games played',
38	  pts: 'points',
39	  trb: 'rebounds',
40	  ast: 'assists',
41	  stl: 'steals',
42	  blk: 'blocks',
43	  fg3: 'three-pointers made',
44	} satisfies Record<BbrStatKey, string>;
45	
46	const BBR_TO_GOLDEN_METRIC = {
47	  g: 'GP',
48	  pts: 'PTS',
49	  trb: 'TRB',
50	  ast: 'AST',
51	  stl: 'STL',
52	  blk: 'BLK',
53	  fg3: 'FG3M',
54	} satisfies Record<BbrStatKey, string>;
55	
56	const BBR_DATA_STAT_ALIASES = {
57	  g: ['games', 'g'],
58	  pts: ['pts'],
59	  trb: ['trb'],
60	  ast: ['ast'],
61	  stl: ['stl'],
62	  blk: ['blk'],
63	  fg3: ['fg3', 'fg3m'],
64	} satisfies Record<BbrStatKey, string[]>;
65	
66	export async function loadAccuracyChecks(path: URL | string): Promise<AccuracyCheck[]> {
67	  const checks = await Bun.file(path).json();
68	
69	  if (!Array.isArray(checks)) {
70	    throw new Error('Accuracy checks file must contain a JSON array');
71	  }
72	
73	  return checks.map((check, index) => validateAccuracyCheck(check, index));
74	}
75	
76	export function compareActual(check: AccuracyCheck, actual: number | null): boolean {
77	  if (actual === null) {
78	    return false;
79	  }
80	
81	  switch (check.mode) {
82	    case 'exact':
83	      return actual === check.expected;
84	    case 'gte':
85	      return actual >= check.expected;
86	    case 'lte':
87	      return actual <= check.expected;
88	    case 'range':
89	      return (
90	        actual >= check.expected - (check.tolerance ?? 0) &&
91	        actual <= check.expected + (check.tolerance ?? 0)
92	      );
93	    case 'approx':
94	      return Math.abs(actual - check.expected) <= (check.tolerance ?? 0);
95	  }
96	}
97	
98	export function formatExpected(check: ExpectedShape): string {
99	  const tolerance = check.tolerance ?? 0;
100	
101	  switch (check.mode) {
102	    case 'gte':
103	      return `>=${check.expected}`;
104	    case 'lte':
105	      return `<=${check.expected}`;
106	    case 'approx':
107	    case 'range':
108	      return `${check.expected}±${tolerance}`;
109	    case 'exact':
110	      return String(check.expected);
111	  }
112	}
113	
114	export function parseBbrCareerTotals(rawHtml: string): BbrCareerTotals {
115	  const html = rawHtml.replace(/<!--([\s\S]*?)-->/g, '$1');
116	  const $ = cheerio.load(html);
117	  const row = $('#totals_stats tfoot tr, #totals tfoot tr')
118	    .filter(
119	      (_, element) =>
120	        parseStatValue(findDataStatText($(element), BBR_DATA_STAT_ALIASES.g)) !== null,
121	    )
122	    .first();
123	  const totals: BbrCareerTotals = {};
124	
125	  for (const stat of Object.keys(BBR_TO_GOLDEN_METRIC) as BbrStatKey[]) {
126	    const value = parseStatValue(findDataStatText(row, BBR_DATA_STAT_ALIASES[stat]));
127	    if (value !== null) {
128	      totals[stat] = value;
129	    }
130	  }
131	
132	  return totals;
133	}
134	
135	export function buildCareerChecks(
136	  player: BbrPlayerSeed,
137	  totals: BbrCareerTotals,
138	  sourcePath: string,
139	): AccuracyCheck[] {
140	  const checks: AccuracyCheck[] = [];
141	  const url = player.url ?? bbrPlayerUrl(player.bbrId);
142	
143	  for (const stat of Object.keys(BBR_TO_GOLDEN_METRIC) as BbrStatKey[]) {
144	    const expected = totals[stat];
145	    if (expected === undefined) {
146	      continue;
147	    }
148	
149	    checks.push({
150	      name: `generated_${slugName(player.name)}_career_${stat}`,
151	      category: 'generated_player_career',
152	      description: `${player.name} career ${BBR_CAREER_STAT_LABELS[stat]} = ${expected}`,
153	      sql: careerSumSql(BBR_TO_GOLDEN_METRIC[stat], player.name),
154	      expected,
155	      mode: 'exact',
156	      source: `Firecrawl BBR player page ${url} cached=${sourcePath} table=totals`,
157	    });
158	  }
159	
160	  return checks;
161	}
162	
163	export function bbrPlayerUrl(bbrId: string): string {
164	  return `https://www.basketball-reference.com/players/${bbrId[0]}/${bbrId}.html`;
165	}
166	
167	function validateAccuracyCheck(value: unknown, index: number): AccuracyCheck {
168	  if (!isObject(value)) {
169	    throw new Error(`Accuracy check at index ${index} must be an object`);
170	  }
171	
172	  const check = value as Record<string, unknown>;
173	  const mode = check['mode'];
174	
175	  if (!isCompareMode(mode)) {
176	    throw new Error(`Accuracy check at index ${index} has invalid mode`);
177	  }
178	
179	  const result: AccuracyCheck = {
180	    name: requireString(check, 'name', index),
181	    category: requireString(check, 'category', index),
182	    description: requireString(check, 'description', index),
183	    sql: requireString(check, 'sql', index),
184	    expected: requireNumber(check, 'expected', index),
185	    mode,
186	    source: requireString(check, 'source', index),
187	  };
188	
189	  if (check['tolerance'] !== undefined) {
190	    result.tolerance = requireNumber(check, 'tolerance', index);
191	  }
192	
193	  return result;
194	}
195	
196	function isObject(value: unknown): value is Record<string, unknown> {
197	  return typeof value === 'object' && value !== null && !Array.isArray(value);
198	}
199	
200	function isCompareMode(value: unknown): value is CompareMode {
201	  return (
202	    value === 'exact' ||
203	    value === 'gte' ||
204	    value === 'lte' ||
205	    value === 'range' ||
206	    value === 'approx'
207	  );
208	}
209	
210	function requireString(check: Record<string, unknown>, field: string, index: number): string {
211	  const value = check[field];
212	  if (typeof value !== 'string' || value.length === 0) {
213	    throw new Error(`Accuracy check at index ${index} requires string field ${field}`);
214	  }
215	  return value;
216	}
217	
218	function requireNumber(check: Record<string, unknown>, field: string, index: number): number {
219	  const value = check[field];
220	  if (typeof value !== 'number' || !Number.isFinite(value)) {
221	    throw new Error(`Accuracy check at index ${index} requires numeric field ${field}`);
222	  }
223	  return value;
224	}
