  const src = distinct ? `(SELECT DISTINCT ${fk} FROM ${child}) c` : `${child} c`;
  return `SELECT count(*) AS n,
    CASE WHEN count(*) > 0 THEN 'orphan ${fk} (not in ${parent}): ' || count(*) END AS details
