import { DuckDBInstance } from '@duckdb/node-api';
const db = await DuckDBInstance.fromCache('./data/nba.duckdb');
const conn = await db.connect();
const q = async (label:string, sql: string) => {
  try { const r = (await conn.runAndReadAll(sql)).getRowObjectsJson(); console.log(`\n### ${label} (${r.length} rows)`); console.log(JSON.stringify(r.slice(0,6))); }
  catch(e:any){ console.log(`\n### ${label} ERROR: ${e.message.split('\n')[0]}`); }
};

// 1. Box-score summation via UNPIVOT, scoped to a recent season for speed
await q('box-summation-unpivot', `
WITH ps AS (
  SELECT game_id, team_id,
    sum(pts) pts, sum(reb) reb, sum(ast) ast, sum(fgm) fgm, sum(fga) fga,
    sum(fg3m) fg3m, sum(fg3a) fg3a, sum(ftm) ftm, sum(fta) fta
  FROM nbadb.fact_player_game_traditional WHERE season_year='2023-24'
  GROUP BY game_id, team_id
),
psu AS (UNPIVOT ps ON pts, reb, ast, fgm, fga, fg3m, fg3a, ftm, fta INTO NAME metric VALUE actual),
tgu AS (UNPIVOT (SELECT game_id, team_id, pts, reb, ast, fgm, fga, fg3m, fg3a, ftm, fta FROM nbadb.fact_team_game WHERE season_year='2023-24') ON pts, reb, ast, fgm, fga, fg3m, fg3a, ftm, fta INTO NAME metric VALUE expected)
SELECT psu.game_id, psu.team_id, psu.metric, tgu.expected, psu.actual, psu.actual - tgu.expected AS delta
FROM psu JOIN tgu USING (game_id, team_id, metric)
WHERE psu.actual IS DISTINCT FROM tgu.expected
LIMIT 10`);

// 2. Continuity: PGT regular-season sum vs agg_player_season, one player-season
await q('continuity-one-player', `
WITH pg AS (
  SELECT p.player_id, p.season_year,
    count(DISTINCT p.game_id) gp, sum(p.pts) pts, sum(p.reb) reb, sum(p.ast) ast
  FROM nbadb.fact_player_game_traditional p
  JOIN nbadb.fact_game_result g ON g.game_id=p.game_id AND g.season_type='Regular'
  WHERE p.season_year='2022-23'
  GROUP BY 1,2
),
ag AS (
  SELECT player_id, season_year, sum(gp) gp, sum(total_pts) pts, sum(total_reb) reb, sum(total_ast) ast
  FROM nbadb.agg_player_season WHERE season_type='Regular' AND season_year='2022-23'
  GROUP BY 1,2
)
SELECT pg.player_id, pg.gp pg_gp, ag.gp ag_gp, pg.pts pg_pts, ag.pts ag_pts
FROM pg JOIN ag USING (player_id, season_year)
WHERE abs(pg.pts - ag.pts) >= 1 OR pg.gp <> ag.gp
LIMIT 10`);

// 3. Record vs standings
await q('record-vs-standings', `
WITH ra AS (
  SELECT season_year, team_id, count(*) FILTER(WHERE win) w, count(*) FILTER(WHERE NOT win) l, count(*) gp
  FROM (
    SELECT season_year, home_team_id team_id, wl_home='W' win FROM nbadb.fact_game_result WHERE season_type='Regular' AND wl_home IS NOT NULL
    UNION ALL
    SELECT season_year, visitor_team_id team_id, wl_home='L' win FROM nbadb.fact_game_result WHERE season_type='Regular' AND wl_home IS NOT NULL
  ) GROUP BY 1,2
),
st AS (SELECT season_year, team_id, wins, losses FROM nbadb.fact_standings WHERE season_type='Regular')
SELECT ra.season_year, ra.team_id, ra.w, st.wins, ra.l, st.losses, ra.gp
FROM ra JOIN st USING (season_year, team_id)
WHERE ra.w <> st.wins OR ra.l <> st.losses
LIMIT 10`);

await q('record-row-counts', `
WITH ra AS (
  SELECT season_year, team_id, count(*) FILTER(WHERE win) w, count(*) FILTER(WHERE NOT win) l, count(*) gp
  FROM (
    SELECT season_year, home_team_id team_id, wl_home='W' win FROM nbadb.fact_game_result WHERE season_type='Regular' AND wl_home IS NOT NULL
    UNION ALL
    SELECT season_year, visitor_team_id team_id, wl_home='L' win FROM nbadb.fact_game_result WHERE season_type='Regular' AND wl_home IS NOT NULL
  ) GROUP BY 1,2
),
st AS (SELECT season_year, team_id, wins, losses FROM nbadb.fact_standings WHERE season_type='Regular')
SELECT count(*) AS standings_team_seasons, count(*) FILTER(WHERE ra.gp <> st.wins+st.losses) AS gp_mismatch
FROM ra JOIN st USING (season_year, team_id)`);
conn.closeSync();
EOF
