    name: 'aggregate_continuity',
    table: 'unified_star.fact_player_season_stats',
    severity: 'MEDIUM',
    dimension: 'consistency',
    rule: 'regular-season game-log totals equal the season-totals row (per player-season)',
    selectSql: `
