        SELECT ra.season_year, ra.team_id, ra.w, ra.l,
          CAST(substr(ra.season_year, 1, 4) AS INT) + 1 AS end_year
        FROM ra LEFT JOIN st USING (season_year, team_id)
        WHERE st.team_id IS NULL
