1	/**
2	 * dq-core.ts — Shared primitives for the data-quality check suites.
3	 *
4	 * Extracted from verify-dq.ts so the internal-consistency registry, the
5	 * cross-table reconciliation suite (verify-cross-table.ts), the advanced-stat
6	 * recompute (verify-advanced-recompute.ts) and the historical boundary scan
7	 * (verify-historical.ts) all share one check shape, one runner, one persistence
8	 * path (audit.dq_results) and one severity gate.
9	 *
10	 * Each check counts *violating* rows. row_count = 0 means the check passed.
11	 * Results are appended to audit.dq_results (history retained for trend tracking);
12	 * a single run shares one `checked_at` timestamp so "latest run" is queryable.
13	 *
14	 * Severity ladder: CRITICAL > HIGH > MEDIUM > LOW > INFO.
15	 *   CRITICAL = physically impossible / breaks the grain (must be zero).
16	 *   HIGH     = strong correctness signal, almost always a genuine defect.
17	 *   MEDIUM   = likely defect or completeness gap; triage + justify residual.
18	 *   LOW/INFO = cosmetic / informational.
19	 */
20	import type { DuckDBConnection } from '@duckdb/node-api';
21	
22	export const DB_PATH = process.env['NBA_DUCKDB_PATH'] ?? './data/nba.duckdb';
23	
24	export type Severity = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'INFO';
25	export type Dimension =
26	  | 'uniqueness'
27	  | 'referential'
28	  | 'consistency'
29	  | 'validity'
30	  | 'completeness'
31	  | 'accuracy';
32	
33	export const SEVERITY_RANK: Record<Severity, number> = {
34	  CRITICAL: 5,
35	  HIGH: 4,
36	  MEDIUM: 3,
37	  LOW: 2,
38	  INFO: 1,
39	};
40	
41	export const SEVERITY_ORDER: Severity[] = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO'];
42	
43	export type CheckSpec = {
44	  /** Stable identifier stored in audit.dq_results.check_name. */
45	  name: string;
46	  /** Fully-qualified table the check is about (stored as table_name). */
47	  table: string;
48	  severity: Severity;
49	  dimension: Dimension;
50	  /** Human-readable statement of the rule that must hold. */
51	  rule: string;
52	  /**
53	   * SQL returning exactly one row with columns:
54	   *   n       BIGINT   — count of violating rows
55	   *   details VARCHAR  — short explanation (NULL when n = 0)
56	   */
57	  countSql: string;
58	};
59	
60	export type Outcome = CheckSpec & { count: number; detail: string | null; error: string | null };
61	
62	// ── Reusable check builders ────────────────────────────────────────────────
63	
64	/** Count rows where `predicate` holds (NULLs in the predicate are not counted). */
65	export function violations(table: string, predicate: string, label: string): string {
66	  return `SELECT count(*) AS n,
67	    CASE WHEN count(*) > 0 THEN '${label}: ' || count(*) || ' rows' END AS details
68	    FROM ${table} WHERE ${predicate}`;
69	}
70	
71	/** Count duplicate grain groups for the given key columns. */
72	export function duplicateGrain(table: string, keys: string[]): string {
73	  const k = keys.join(', ');
74	  return `SELECT count(*) AS n,
75	    CASE WHEN count(*) > 0 THEN 'duplicate (${k}) groups: ' || count(*) END AS details
76	    FROM (SELECT ${k} FROM ${table} GROUP BY ${k} HAVING count(*) > 1)`;
77	}
78	
79	/** Count child rows whose non-null FK has no matching parent PK (orphans). */
80	export function orphans(
81	  child: string,
82	  fk: string,
83	  parent: string,
84	  pk: string,
85	  distinct = false,
86	): string {
87	  const src = distinct ? `(SELECT DISTINCT ${fk} FROM ${child}) c` : `${child} c`;
88	  return `SELECT count(*) AS n,
89	    CASE WHEN count(*) > 0 THEN 'orphan ${fk} (not in ${parent}): ' || count(*) END AS details
90	    FROM ${src}
91	    WHERE c.${fk} IS NOT NULL
92	      AND NOT EXISTS (SELECT 1 FROM ${parent} p WHERE p.${pk} = c.${fk})`;
93	}
94	
95	/** Count rows missing any required grain/key column. */
96	export function requiredColumns(table: string, columns: string[], label: string): string {
97	  const predicate = columns.map((col) => `${col} IS NULL`).join(' OR ');
98	  return violations(table, predicate, label);
99	}
100	
101	// ── Argument parsing ───────────────────────────────────────────────────────
102	
103	export type StandardArgs = { dryRun: boolean; gate: Severity; filter: string | null };
104	
105	export function parseStandardArgs(argv: string[]): StandardArgs {
106	  const args = argv.slice(2);
107	  const dryRun = args.includes('--dry-run');
108	  const gateArg = args.find((a) => a.startsWith('--gate='));
109	  const filterArg = args.find((a) => a.startsWith('--filter='));
110	  const gate = (gateArg?.split('=')[1]?.toUpperCase() as Severity) ?? 'CRITICAL';
111	  const filter = filterArg?.split('=')[1] ?? null;
112	  if (!(gate in SEVERITY_RANK)) {
113	    throw new Error(`--gate must be one of ${Object.keys(SEVERITY_RANK).join(', ')}`);
114	  }
115	  return { dryRun, gate, filter };
116	}
117	
118	/** Timestamp shared by every row written in a single run. */
119	export function newRunId(): string {
120	  return new Date().toISOString().replace('T', ' ').replace('Z', '');
121	}
122	
123	// ── Execution ──────────────────────────────────────────────────────────────
124	
125	/** Execute each check's countSql and collect outcomes (errors captured, not thrown). */
126	export async function runCountChecks(
127	  conn: DuckDBConnection,
128	  checks: CheckSpec[],
129	): Promise<Outcome[]> {
130	  const outcomes: Outcome[] = [];
131	  for (const check of checks) {
132	    try {
133	      const res = await conn.runAndReadAll(check.countSql);
134	      const row = res.getRowObjectsJson()[0] ?? {};
135	      const count = Number(row['n'] ?? 0);
136	      const detail = (row['details'] as string | null) ?? null;
137	      outcomes.push({ ...check, count, detail, error: null });
138	    } catch (e: unknown) {
139	      const message = e instanceof Error ? e.message : String(e);
140	      outcomes.push({ ...check, count: -1, detail: null, error: message });
141	    }
142	  }
143	  return outcomes;
144	}
145	
146	/**
147	 * Append one row per (non-errored) outcome to audit.dq_results and flush the WAL.
148	 * Checks that failed to execute are skipped (their ERROR shows only in the report).
149	 */
150	export async function persistResults(
151	  conn: DuckDBConnection,
152	  outcomes: Outcome[],
153	  runId: string,
154	): Promise<void> {
155	  await conn.run('CREATE SCHEMA IF NOT EXISTS audit');
156	  for (const o of outcomes) {
157	    if (o.error) continue;
158	    const detailSql = o.detail === null ? 'NULL' : `'${o.detail.replace(/'/g, "''")}'`;
159	    await conn.run(
160	      `INSERT INTO audit.dq_results (check_name, table_name, severity, row_count, details, checked_at)
161	       VALUES ('${o.name}', '${o.table}', '${o.severity}', ${o.count}, ${detailSql}, TIMESTAMP '${runId}')`,
162	    );
163	  }
164	  await conn.run('CHECKPOINT'); // flush WAL → avoid cross-process replay bug
165	}
166	
167	// ── Reporting & gating ──────────────────────────────────────────────────────
168	
169	const pad = (s: string, n: number) => s.padEnd(n);
170	
171	export type ReportOptions = {
172	  title: string;
173	  runId: string;
174	  dryRun: boolean;
175	  gate: Severity;
176	  checkCount: number;
177	};
178	
179	export function printReport(outcomes: Outcome[], opts: ReportOptions): void {
180	  const sorted = [...outcomes].sort(
181	    (a, b) =>
182	      SEVERITY_RANK[b.severity] - SEVERITY_RANK[a.severity] ||
183	      b.count - a.count ||
184	      a.name.localeCompare(b.name),
185	  );
186	
187	  console.log(
188	    `\n${opts.title} — run ${opts.runId}${opts.dryRun ? ' (dry-run, not persisted)' : ''}`,
189	  );
190	  console.log(`DB: ${DB_PATH} · checks: ${opts.checkCount} · gate: ${opts.gate}\n`);
191	  console.log(
192	    `${pad('SEV', 9)}${pad('CHECK', 40)}${pad('TABLE', 40)}${pad('VIOLATIONS', 12)}DETAIL`,
193	  );
194	  console.log('─'.repeat(120));
195	  for (const o of sorted) {
196	    const v = o.error ? 'ERROR' : o.count === 0 ? 'ok' : String(o.count);
197	    const detail = o.error ? o.error : (o.detail ?? '');
198	    console.log(
199	      `${pad(o.severity, 9)}${pad(o.name, 40)}${pad(o.table.replace('nbadb.', ''), 40)}${pad(v, 12)}${detail}`,
200	    );
201	  }
202	

